1	package main
2	
3	import (
4		"fmt"
5		"io"
6		"os"
7		"path/filepath"
8		"slices"
9		"sort"
10		"strings"
11	
12		"github.com/pdfcpu/pdfcpu/pkg/api"
13	)
14	
15	// mergePDFs interleaves pages from pathA and pathB into outPath.
16	// If firstPageInA is true, file A contributes the odd-numbered output pages (1, 3, 5, …);
17	// otherwise file B does. If reverseB is true, file B's pages are reversed before interleaving,
18	// which is the typical case when the paper stack was flipped between scans.
19	// If the page counts differ, the extra pages from the longer file are
20	// appended in order after the interleaved section.
21	func mergePDFs(pathA, pathB, outPath string, firstPageInA, reverseB bool, skipA, skipB []int, rotationsA, rotationsB map[int]int) error {
22		tmpDir, err := os.MkdirTemp("", "psp-merge-*")
23		if err != nil {
24			return err
25		}
26		defer os.RemoveAll(tmpDir)
27	
28		dirA := filepath.Join(tmpDir, "a")
29		dirB := filepath.Join(tmpDir, "b")
30		for _, d := range []string{dirA, dirB} {
31			if err := os.MkdirAll(d, 0o755); err != nil {
32				return err
33			}
34		}
35	
36		if err := api.SplitFile(pathA, dirA, 1, nil); err != nil {
37			return fmt.Errorf("splitting file A: %w", err)
38		}
39		if err := api.SplitFile(pathB, dirB, 1, nil); err != nil {
40			return fmt.Errorf("splitting file B: %w", err)
41		}
42	
43		pagesA, err := sortedPDFsInDir(dirA)
44		if err != nil {
45			return fmt.Errorf("listing file A pages: %w", err)
46		}
47		pagesB, err := sortedPDFsInDir(dirB)
48		if err != nil {
49			return fmt.Errorf("listing file B pages: %w", err)
50		}
51	
52		pagesA = filterSkipped(pagesA, skipA)
53		pagesB = filterSkipped(pagesB, skipB)
54		if reverseB {
55			slices.Reverse(pagesB)
56		}
57	
58		if err := applyRotations(pagesA, rotationsA); err != nil {
59			return fmt.Errorf("rotating file A pages: %w", err)
60		}
61		if err := applyRotations(pagesB, rotationsB); err != nil {
62			return fmt.Errorf("rotating file B pages: %w", err)
63		}
64	
65		if firstPageInA {
66			return api.MergeCreateFile(interleave(pagesA, pagesB), outPath, false, nil)
67		}
68		return api.MergeCreateFile(interleave(pagesB, pagesA), outPath, false, nil)
69	}
70	
71	func filterSkipped(pages []string, skip []int) []string {
72		if len(skip) == 0 {
73			return pages
74		}
75		skipSet := make(map[int]bool, len(skip))
76		for _, p := range skip {
77			skipSet[p] = true
78		}
79		out := make([]string, 0, len(pages))
80		for i, p := range pages {
81			if !skipSet[i+1] {
82				out = append(out, p)
83			}
84		}
85		return out
86	}
87	
88	// applyRotations rotates individual single-page PDF files in-place according to
89	// the rotations map (1-indexed page number → clockwise degrees: 90, 180, 270).
90	// The page number is derived from the pdfcpu split filename.
91	func applyRotations(pages []string, rotations map[int]int) error {
92		for _, p := range pages {
93			origPage, err := pdfFromPage(filepath.Base(p))
94			if err != nil {
95				return err
96			}
97			rot, ok := rotations[origPage]
98			if !ok || rot == 0 {
99				continue
100			}
101			tmp := p + ".rot.pdf"
102			if err := api.RotateFile(p, tmp, rot, nil, nil); err != nil {
103				return fmt.Errorf("page %d: %w", origPage, err)
104			}
105			if err := os.Rename(tmp, p); err != nil {
106				return err
107			}
108		}
109		return nil
110	}
111	
112	// splitPDF assembles each output file by extracting pages from inPath in the
113	// order specified by each spec's Pages slice, applying rotations, and writing
114	// the results to outDir. Pages are 1-indexed original page numbers; skip
115	// filtering and reordering have already been applied by the caller.
116	func splitPDF(inPath string, files []OutputFileSpec, rotations map[int]int, outDir string) ([]string, error) {
117		tmpDir, err := os.MkdirTemp("", "psp-split-pages-*")
118		if err != nil {
119			return nil, err
120		}
121		defer os.RemoveAll(tmpDir)
122	
123		if err := api.SplitFile(inPath, tmpDir, 1, nil); err != nil {
124			return nil, fmt.Errorf("splitting to single pages: %w", err)
125		}
126		allPages, err := sortedPDFsInDir(tmpDir)
127		if err != nil {
128			return nil, fmt.Errorf("listing single pages: %w", err)
129		}
130	
131		if err := applyRotations(allPages, rotations); err != nil {
132			return nil, fmt.Errorf("rotating pages: %w", err)
133		}
134	
135		var outPaths []string
136		for i, spec := range files {
137			if len(spec.Pages) == 0 {
138				return nil, fmt.Errorf("output file %d has no pages", i+1)
139			}
140			segPages := make([]string, 0, len(spec.Pages))
141			for _, pageNum := range spec.Pages {
142				if pageNum < 1 || pageNum > len(allPages) {
143					return nil, fmt.Errorf("output file %d: page %d out of range", i+1, pageNum)
144				}
145				segPages = append(segPages, allPages[pageNum-1])
146			}
147			outPath := filepath.Join(outDir, fmt.Sprintf("segment-%d.pdf", i+1))
148			if err := api.MergeCreateFile(segPages, outPath, false, nil); err != nil {
149				return nil, fmt.Errorf("building segment %d: %w", i+1, err)
150			}
151			outPaths = append(outPaths, outPath)
152		}
153		return outPaths, nil
154	}
155	
156	// pdfPageCount returns the number of pages in the PDF at path.
157	func pdfPageCount(path string) (int, error) {
158		return api.PageCountFile(path)
159	}
160	
161	// sortedPDFsInDir lists PDF files in dir sorted numerically by the first page
162	// number encoded in pdfcpu's output filenames (e.g. "doc_3-5.pdf" → 3).
163	func sortedPDFsInDir(dir string) ([]string, error) {
164		entries, err := os.ReadDir(dir)
165		if err != nil {
166			return nil, err
167		}
168		type item struct {
169			path     string
170			fromPage int
171		}
172		var files []item
173		for _, e := range entries {
174			if e.IsDir() || !strings.HasSuffix(strings.ToLower(e.Name()), ".pdf") {
175				continue
176			}
177			fromPage, err := pdfFromPage(e.Name())
178			if err != nil {
179				return nil, err
180			}
181			files = append(files, item{
182				path:     filepath.Join(dir, e.Name()),
183				fromPage: fromPage,
184			})
185		}
186		sort.Slice(files, func(i, j int) bool { return files[i].fromPage < files[j].fromPage })
187		result := make([]string, len(files))
188		for i, f := range files {
189			result[i] = f.path
190		}
191		return result, nil
192	}
193	
194	// interleave merges two slices by alternating elements: a[0], b[0], a[1], b[1], ...
195	// If the slices have different lengths, the remaining elements of the longer
196	// slice are appended in order after the interleaved section.
197	func interleave[T any](a, b []T) []T {
198		n := min(len(a), len(b))
199		out := make([]T, 0, len(a)+len(b))
200		for i := range n {
201			out = append(out, a[i], b[i])
202		}
203		out = append(out, a[n:]...)
204		out = append(out, b[n:]...)
205		return out
206	}
207	
208	func copyFile(src, dst string) error {
209		in, err := os.Open(src)
210		if err != nil {
211			return err
212		}
213		defer in.Close()
214		out, err := os.Create(dst)
215		if err != nil {
216			return err
217		}
218		defer out.Close()
219		if _, err = io.Copy(out, in); err != nil {
220			return err
221		}
222		return out.Sync()
223	}
224	
225	// pdfFromPage extracts the first page number from a pdfcpu split filename
