336		// Interleaved order: page1=A1(0°), page2=B1(180°), page3=A2(90°), page4=B2(0°), page5=A3(0°), page6=B3(0°)
337		wantRotations := []int{0, 180, 90, 0, 0, 0}
338		for i, want := range wantRotations {
