348		tmp := t.TempDir()
349		in := filepath.Join(tmp, "input.pdf")
350		outDir := filepath.Join(tmp, "out")
351		if err := os.MkdirAll(outDir, 0o755); err != nil {
352			t.Fatal(err)
353		}
354	
355		writePDF(t, in, []string{"P1", "P2", "P3", "P4", "P5", "P6"})
356	
357		parts, err := splitPDF(in, []OutputFileSpec{
358			{Pages: []int{1, 2}},
359			{Pages: []int{3, 4}},
360			{Pages: []int{5, 6}},
361		}, nil, outDir)
362		if err != nil {
363			t.Fatal(err)
364		}
365	
366		if len(parts) != 3 {
367			t.Fatalf("got %d parts, want 3", len(parts))
368		}
