package main

import (
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func TestScanLocalRootFilesInRootAndSubfolder(t *testing.T) {
	root := t.TempDir()
	writePDF(t, filepath.Join(root, "misc.pdf"), []string{"p1", "p2"})
	if err := os.Mkdir(filepath.Join(root, "invoices"), 0o755); err != nil {
		t.Fatal(err)
	}
	writePDF(t, filepath.Join(root, "invoices", "b.pdf"), []string{"p1"})
	writePDF(t, filepath.Join(root, "invoices", "a.pdf"), []string{"p1", "p2", "p3"})

	tree, err := scanLocalRoot(root)
	if err != nil {
		t.Fatal(err)
	}

	if tree.Name != "" {
		t.Errorf("root name = %q, want \"\"", tree.Name)
	}
	if len(tree.Files) != 1 || tree.Files[0].Name != "misc.pdf" || !tree.Files[0].IsPDF || tree.Files[0].PageCount != 2 {
		t.Errorf("root files = %+v", tree.Files)
	}
	if tree.Files[0].SizeBytes <= 0 {
		t.Errorf("root file size = %d, want > 0", tree.Files[0].SizeBytes)
	}

	if len(tree.Subgroups) != 1 {
		t.Fatalf("got %d subgroups, want 1: %+v", len(tree.Subgroups), tree.Subgroups)
	}
	sub := tree.Subgroups[0]
	if sub.Name != "invoices" {
		t.Errorf("subgroup name = %q, want invoices", sub.Name)
	}
	if len(sub.Files) != 2 {
		t.Fatalf("got %d files in invoices, want 2: %+v", len(sub.Files), sub.Files)
	}
	// alphabetical by filename
	if sub.Files[0].Name != "a.pdf" || sub.Files[1].Name != "b.pdf" {
		t.Errorf("invoices files not sorted: %+v", sub.Files)
	}
	if sub.Files[0].PageCount != 3 || sub.Files[1].PageCount != 1 {
		t.Errorf("unexpected page counts: %+v", sub.Files)
	}
}

func TestScanLocalRootEmptySubfolderOmitted(t *testing.T) {
	root := t.TempDir()
	if err := os.Mkdir(filepath.Join(root, "empty"), 0o755); err != nil {
		t.Fatal(err)
	}
	writePDF(t, filepath.Join(root, "top.pdf"), []string{"p1"})

	tree, err := scanLocalRoot(root)
	if err != nil {
		t.Fatal(err)
	}
	if len(tree.Subgroups) != 0 {
		t.Fatalf("expected the empty subfolder to be omitted, got %+v", tree.Subgroups)
	}
	if len(tree.Files) != 1 || tree.Files[0].Name != "top.pdf" {
		t.Errorf("root files = %+v", tree.Files)
	}
}

func TestScanLocalRootFlagsCorruptPDF(t *testing.T) {
	root := t.TempDir()
	writePDF(t, filepath.Join(root, "good.pdf"), []string{"p1"})
	if err := os.WriteFile(filepath.Join(root, "bad.pdf"), []byte("not a pdf"), 0o644); err != nil {
		t.Fatal(err)
	}

	tree, err := scanLocalRoot(root)
	if err != nil {
		t.Fatal(err)
	}
	if len(tree.Files) != 2 {
		t.Fatalf("expected both files to appear in the scan, got %+v", tree.Files)
	}

	files := tree.Files
	if files[0].Name != "bad.pdf" || !files[0].Corrupt || files[0].PageCount != 0 {
		t.Errorf("bad.pdf = %+v, want Corrupt=true, PageCount=0", files[0])
	}
	if files[0].SizeBytes <= 0 {
		t.Errorf("bad.pdf size = %d, want > 0", files[0].SizeBytes)
	}
	if files[1].Name != "good.pdf" || files[1].Corrupt || files[1].PageCount != 1 {
		t.Errorf("good.pdf = %+v, want Corrupt=false, PageCount=1", files[1])
	}
}

func TestScanLocalRootIncludesNonPDFFilesButIgnoresDotfiles(t *testing.T) {
	root := t.TempDir()
	writePDF(t, filepath.Join(root, "doc.pdf"), []string{"p1"})
	if err := os.WriteFile(filepath.Join(root, "scan.jpg"), []byte("hi"), 0o644); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(root, ".DS_Store"), []byte("hi"), 0o644); err != nil {
		t.Fatal(err)
	}
	if err := os.Mkdir(filepath.Join(root, ".hidden"), 0o755); err != nil {
		t.Fatal(err)
	}
	writePDF(t, filepath.Join(root, ".hidden", "sneaky.pdf"), []string{"p1"})

	tree, err := scanLocalRoot(root)
	if err != nil {
		t.Fatal(err)
	}
	if len(tree.Files) != 2 {
		t.Fatalf("expected doc.pdf and scan.jpg, got %+v", tree.Files)
	}
	// alphabetical by filename
	doc, img := tree.Files[0], tree.Files[1]
	if doc.Name != "doc.pdf" || !doc.IsPDF || doc.Corrupt || doc.PageCount != 1 {
		t.Errorf("doc.pdf = %+v, want IsPDF=true, Corrupt=false, PageCount=1", doc)
	}
	if img.Name != "scan.jpg" || img.IsPDF || img.Corrupt || img.PageCount != 0 {
		t.Errorf("scan.jpg = %+v, want IsPDF=false, Corrupt=false, PageCount=0", img)
	}
	if img.SizeBytes <= 0 {
		t.Errorf("scan.jpg size = %d, want > 0", img.SizeBytes)
	}
	if len(tree.Subgroups) != 0 {
		t.Errorf("expected .hidden to be ignored, got subgroups %+v", tree.Subgroups)
	}
}

func TestScanLocalRootRecursesMultipleLevels(t *testing.T) {
	root := t.TempDir()
	nested := filepath.Join(root, "a", "b")
	if err := os.MkdirAll(nested, 0o755); err != nil {
		t.Fatal(err)
	}
	writePDF(t, filepath.Join(nested, "deep.pdf"), []string{"p1"})
	writePDF(t, filepath.Join(root, "a", "shallow.pdf"), []string{"p1"})

	tree, err := scanLocalRoot(root)
	if err != nil {
		t.Fatal(err)
	}
	if len(tree.Files) != 0 {
		t.Errorf("root files = %+v, want none", tree.Files)
	}
	if len(tree.Subgroups) != 1 || tree.Subgroups[0].Name != "a" {
		t.Fatalf("expected a single top-level subgroup \"a\", got %+v", tree.Subgroups)
	}

	a := tree.Subgroups[0]
	if len(a.Files) != 1 || a.Files[0].Name != "shallow.pdf" {
		t.Errorf("a's direct files = %+v, want just shallow.pdf", a.Files)
	}
	if len(a.Subgroups) != 1 || a.Subgroups[0].Name != "b" {
		t.Fatalf("a's subgroups = %+v, want a single subgroup \"b\"", a.Subgroups)
	}

	b := a.Subgroups[0]
	if len(b.Files) != 1 || b.Files[0].Name != "deep.pdf" {
		t.Errorf("b's files = %+v, want just deep.pdf", b.Files)
	}
	if len(b.Subgroups) != 0 {
		t.Errorf("b's subgroups = %+v, want none", b.Subgroups)
	}
}

func TestScanLocalRootOmitsSubtreeWithNoPDFsAtAnyDepth(t *testing.T) {
	root := t.TempDir()
	emptyNested := filepath.Join(root, "empty", "also-empty")
	if err := os.MkdirAll(emptyNested, 0o755); err != nil {
		t.Fatal(err)
	}
	writePDF(t, filepath.Join(root, "top.pdf"), []string{"p1"})

	tree, err := scanLocalRoot(root)
	if err != nil {
		t.Fatal(err)
	}
	if len(tree.Subgroups) != 0 {
		t.Fatalf("expected the empty subtree to be omitted, got %+v", tree.Subgroups)
	}
}

func TestScanLocalRootDoesNotFollowSymlinkedDirectories(t *testing.T) {
	root := t.TempDir()
	real := filepath.Join(root, "real")
	if err := os.Mkdir(real, 0o755); err != nil {
		t.Fatal(err)
	}
	writePDF(t, filepath.Join(real, "doc.pdf"), []string{"p1"})

	// A symlink back to an ancestor would form an infinite loop if followed.
	if err := os.Symlink(root, filepath.Join(real, "loop")); err != nil {
		t.Fatal(err)
	}

	tree, err := scanLocalRoot(root)
	if err != nil {
		t.Fatal(err)
	}
	if len(tree.Subgroups) != 1 || tree.Subgroups[0].Name != "real" || len(tree.Subgroups[0].Subgroups) != 0 {
		t.Fatalf("expected only the real directory with no subgroups (symlink not followed), got %+v", tree.Subgroups)
	}
}

func TestScanLocalRootSubfoldersSortedAlphabetically(t *testing.T) {
	root := t.TempDir()
	for _, name := range []string{"zeta", "alpha", "mid"} {
		dir := filepath.Join(root, name)
		if err := os.Mkdir(dir, 0o755); err != nil {
			t.Fatal(err)
		}
		writePDF(t, filepath.Join(dir, "f.pdf"), []string{"p1"})
	}

	tree, err := scanLocalRoot(root)
	if err != nil {
		t.Fatal(err)
	}
	if len(tree.Subgroups) != 3 {
		t.Fatalf("got %d subgroups, want 3: %+v", len(tree.Subgroups), tree.Subgroups)
	}
	got := []string{tree.Subgroups[0].Name, tree.Subgroups[1].Name, tree.Subgroups[2].Name}
	want := []string{"alpha", "mid", "zeta"}
	for i := range want {
		if got[i] != want[i] {
			t.Errorf("subgroup order = %v, want %v", got, want)
			break
		}
	}
}

func TestScanLocalRootReturnsEmptyTreeForEmptyFolder(t *testing.T) {
	root := t.TempDir()

	tree, err := scanLocalRoot(root)
	if err != nil {
		t.Fatal(err)
	}
	if len(tree.Files) != 0 || len(tree.Subgroups) != 0 {
		t.Errorf("expected an empty (not omitted) root, got %+v", tree)
	}
}

// TestScanLocalRootJSONNeverUsesNullForSlices guards against Go's nil-slice
// marshaling to JSON `null` instead of `[]`, which crashes the frontend
// (e.g. `group.subgroups.length` throws on null). A leaf group (no
// subfolders) is exactly the case that previously produced a nil Subgroups
// slice.
func TestScanLocalRootJSONNeverUsesNullForSlices(t *testing.T) {
	root := t.TempDir()
	writePDF(t, filepath.Join(root, "leaf.pdf"), []string{"p1"})
	if err := os.Mkdir(filepath.Join(root, "childless"), 0o755); err != nil {
		t.Fatal(err)
	}
	writePDF(t, filepath.Join(root, "childless", "doc.pdf"), []string{"p1"})

	tree, err := scanLocalRoot(root)
	if err != nil {
		t.Fatal(err)
	}

	data, err := json.Marshal(tree)
	if err != nil {
		t.Fatal(err)
	}
	if strings.Contains(string(data), "null") {
		t.Errorf("JSON output contains null (should be [] for empty slices): %s", data)
	}
}

package main

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"sync"

	"golang.org/x/oauth2"
	"golang.org/x/oauth2/google"
	"google.golang.org/api/drive/v3"
	"google.golang.org/api/option"
)

const driveOAuthPort = "8765"
const driveOAuthCallbackPath = "/oauth/callback"

// driveClientMu serializes driveService calls. Without it, two concurrent
// callers needing a token refresh or a fresh OAuth flow would each try to
// bind driveOAuthPort for the callback server, and the loser would fail with
// "address already in use" even though the winner's call succeeds.
var driveClientMu sync.Mutex

// openBrowser launches url in the system default browser. Overridden in
// tests to simulate the user completing the consent flow, instead of
// actually opening a browser.
var openBrowser = func(url string) error { return exec.Command("open", url).Run() }

// driveConfigDir returns (and creates) ~/Library/Application Support/paper-scan-processor.
func driveConfigDir() (string, error) {
	base, err := os.UserConfigDir()
	if err != nil {
		return "", err
	}
	dir := filepath.Join(base, "paper-scan-processor")
	return dir, os.MkdirAll(dir, 0o700)
}

func driveOAuthConfig() (*oauth2.Config, error) {
	dir, err := driveConfigDir()
	if err != nil {
		return nil, err
	}
	credPath := filepath.Join(dir, "drive_credentials.json")
	data, err := os.ReadFile(credPath)
	if err != nil {
		return nil, fmt.Errorf("read %s: %w", credPath, err)
	}
	cfg, err := google.ConfigFromJSON(data, drive.DriveScope)
	if err != nil {
		return nil, fmt.Errorf("parse credentials: %w", err)
	}
	// Override to match our local callback server.
	// In Google Cloud Console, register http://localhost as an authorized redirect URI.
	cfg.RedirectURL = "http://localhost:" + driveOAuthPort + driveOAuthCallbackPath
	return cfg, nil
}

// driveService returns an authenticated client for the Google Drive API.
// On first call, or whenever the stored refresh token has expired or been
// revoked, it opens the system default browser to perform the OAuth flow and
// saves the resulting token for reuse in future sessions.
func driveService(ctx context.Context) (*drive.Service, error) {
	driveClientMu.Lock()
	defer driveClientMu.Unlock()

	cfg, err := driveOAuthConfig()
	if err != nil {
		return nil, err
	}

	dir, err := driveConfigDir()
	if err != nil {
		return nil, err
	}
	client, err := driveClientWithConfig(ctx, cfg, filepath.Join(dir, "drive_token.json"), driveRunOAuthFlow)
	if err != nil {
		return nil, err
	}
	return drive.NewService(ctx, option.WithHTTPClient(client))
}

// reauthFunc performs a full OAuth flow, returning a fresh token pair.
// driveRunOAuthFlow is the production implementation; tests substitute a stub.
type reauthFunc func(ctx context.Context, cfg *oauth2.Config) (*oauth2.Token, error)

// driveClientWithConfig holds driveService's refresh/reauth decision logic,
// parameterized over cfg, tokenPath, and the reauth function so tests can
// supply a fake token endpoint (via cfg.Endpoint.TokenURL) and a stubbed
// reauth instead of hitting Google or opening a real browser.
func driveClientWithConfig(ctx context.Context, cfg *oauth2.Config, tokenPath string, reauth reauthFunc) (*http.Client, error) {
	// storedToken bundles both the short-lived access token and the
	// long-lived refresh token last persisted to disk.
	if storedToken, err := driveLoadToken(tokenPath); err == nil {
		src := cfg.TokenSource(ctx, storedToken)
		refreshedToken, err := src.Token()
		if err == nil {
			if refreshedToken.AccessToken != storedToken.AccessToken {
				// storedToken.AccessToken had expired, so Token() used
				// storedToken.RefreshToken to obtain a new access token from
				// Google. Persist the pair so future calls reuse it instead
				// of refreshing again.
				if err := driveSaveToken(tokenPath, refreshedToken); err != nil {
					return nil, fmt.Errorf("save refreshed token: %w", err)
				}
			}
			return oauth2.NewClient(ctx, oauth2.StaticTokenSource(refreshedToken)), nil
		}
		var retrieveErr *oauth2.RetrieveError
		if !errors.As(err, &retrieveErr) || retrieveErr.ErrorCode != "invalid_grant" {
			return nil, fmt.Errorf("refresh token: %w", err)
		}
		// storedToken.RefreshToken is dead (expired or revoked) — fall
		// through to re-authenticate from scratch.
	}

	// newToken is a freshly issued access token/refresh token pair from a
	// full browser-based OAuth exchange.
	newToken, err := reauth(ctx, cfg)
	if err != nil {
		return nil, err
	}
	if err := driveSaveToken(tokenPath, newToken); err != nil {
		return nil, fmt.Errorf("save token: %w", err)
	}
	return cfg.Client(ctx, newToken), nil
}

var _ reauthFunc = driveRunOAuthFlow // driveRunOAuthFlow must match reauthFunc's signature

func driveRunOAuthFlow(ctx context.Context, cfg *oauth2.Config) (*oauth2.Token, error) {
	codeCh := make(chan string, 1)
	errCh := make(chan error, 1)

	mux := http.NewServeMux()
	srv := &http.Server{Addr: ":" + driveOAuthPort, Handler: mux}

	mux.HandleFunc(driveOAuthCallbackPath, func(w http.ResponseWriter, r *http.Request) {
		code := r.URL.Query().Get("code")
		if code == "" {
			http.Error(w, "missing code", http.StatusBadRequest)
			errCh <- fmt.Errorf("OAuth callback: missing code parameter")
			return
		}
		fmt.Fprint(w, "<html><body><h1>Authenticated</h1><p>You can close this tab.</p></body></html>")
		codeCh <- code
	})

	go func() {
		if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			errCh <- err
		}
	}()
	defer srv.Shutdown(context.Background()) //nolint:errcheck

	authURL := cfg.AuthCodeURL("", oauth2.AccessTypeOffline)
	if err := openBrowser(authURL); err != nil {
		return nil, fmt.Errorf("open browser: %w", err)
	}

	select {
	case code := <-codeCh:
		return cfg.Exchange(ctx, code)
	case err := <-errCh:
		return nil, err
	case <-ctx.Done():
		return nil, ctx.Err()
	}
}

func driveLoadToken(path string) (*oauth2.Token, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	var t oauth2.Token
	return &t, json.NewDecoder(f).Decode(&t)
}

func driveSaveToken(path string, token *oauth2.Token) error {
	f, err := os.Create(path)
	if err != nil {
		return err
	}
	defer f.Close()
	return json.NewEncoder(f).Encode(token)
}

