		}
		outPath := filepath.Join(outDir, fmt.Sprintf("segment-%d.pdf", i+1))
		if err := api.MergeCreateFile(segPages, outPath, false, nil); err != nil {
			return nil, fmt.Errorf("building segment %d: %w", i+1, err)
		}
