				subgroups = append(subgroups, sub)
			}
			continue
		}

		path := filepath.Join(dir, entryName)
		info, err := os.Stat(path)
		if err != nil {
			continue
		}

		isPDF := strings.HasSuffix(strings.ToLower(entryName), ".pdf")
		var count int
		var corrupt bool
		if isPDF {
			count, err = pdf.PageCount(path)
