237	// hitCallback simulates a browser completing the OAuth consent flow by
238	// requesting driveRunOAuthFlow's local callback URL directly. It retries
239	// briefly since the callback server's listener may not be bound yet by the
240	// time openBrowser is invoked (the same race that exists against a real
241	// browser, which takes far longer than this loop's window to respond).
242	func hitCallback(t *testing.T, query string) error {
243		t.Helper()
244		url := "http://localhost:" + driveOAuthPort + driveOAuthCallbackPath + query
245		deadline := time.Now().Add(2 * time.Second)
246		var lastErr error
247		for time.Now().Before(deadline) {
248			resp, err := http.Get(url)
249			if err == nil {
250				resp.Body.Close()
251				return nil
252			}
253			lastErr = err
254			time.Sleep(5 * time.Millisecond)
255		}
256		return lastErr
257	}
