272	
273		withStubOpenBrowser(t, func(string) error { return hitCallback(t, "?code=test-code") })
274	
275		token, err := driveRunOAuthFlow(context.Background(), cfg)
276		if err != nil {
277			t.Fatalf("driveRunOAuthFlow: %v", err)
278		}
279		if token.AccessToken != "exchanged-access" {
280			t.Errorf("AccessToken = %q, want %q", token.AccessToken, "exchanged-access")
281		}
282	}
