284	func TestDriveRunOAuthFlowMissingCode(t *testing.T) {
285		cfg := fakeOAuthConfig("http://example.invalid/token") // never dialed: code exchange never happens
286	
287		withStubOpenBrowser(t, func(string) error { return hitCallback(t, "") })
288	
289		_, err := driveRunOAuthFlow(context.Background(), cfg)
290		if err == nil || !strings.Contains(err.Error(), "missing code parameter") {
291			t.Fatalf("driveRunOAuthFlow error = %v, want it to mention a missing code parameter", err)
292		}
293	}
