295	func TestDriveRunOAuthFlowContextCanceled(t *testing.T) {
296		cfg := fakeOAuthConfig("http://example.invalid/token") // never dialed
297	
298		withStubOpenBrowser(t, func(string) error { return nil }) // never completes the callback
299	
300		ctx, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)
301		defer cancel()
302	
303		_, err := driveRunOAuthFlow(ctx, cfg)
304		if !errors.Is(err, context.DeadlineExceeded) {
305			t.Fatalf("driveRunOAuthFlow error = %v, want context.DeadlineExceeded", err)
306		}
307	}
