317	
318		withStubOpenBrowser(t, func(string) error { return nil }) // nothing listening for HTTP on this port anyway
319	
320		_, err = driveRunOAuthFlow(context.Background(), cfg)
321		if err == nil || !strings.Contains(err.Error(), "address already in use") {
322			t.Fatalf("driveRunOAuthFlow error = %v, want it to mention the port already being in use", err)
323		}
324	}
